import mujoco, numpy as np, time
base=open('model_ref.xml').read()
def sim(model, seed, nstep=None):
    data=mujoco.MjData(model)
    if nstep is None: nstep=int(2.0/model.opt.timestep)
    rng=np.random.default_rng(seed)
    data.qpos+=rng.normal(0,0.01,size=data.qpos.shape)
    mujoco.mj_forward(model,data)
    for _ in range(nstep):
        mujoco.mj_step(model,data)
    return data
def timeit(m,n=20):
    ts=[]
    for _ in range(n):
        t=time.perf_counter(); sim(m,np.random.randint(0,9999)); ts.append(time.perf_counter()-t)
    return np.median(ts)
def mk(opt):
    return mujoco.MjModel.from_xml_string(base.replace('<compiler autolimits="true"/>','<compiler autolimits="true"/>\n  %s'%opt))
tests={
 'ref': '',
 'dense_nc_it1': '<option jacobian="dense" iterations="1"><flag contact="disable"/></option>',
 'nc_noconstraint': '<option jacobian="dense"><flag contact="disable" constraint="disable"/></option>',
 'nc_nopassive': '<option jacobian="dense" iterations="1"><flag contact="disable" passive="disable"/></option>',
