 'all_off': '<option jacobian="dense"><flag contact="disable" constraint="disable" passive="disable"/></option>',
}
for name,opt in tests.items():
    m=mk(opt) if opt else mujoco.MjModel.from_xml_path('model_ref.xml')
    print(f'{name:20s} {timeit(m):.4f}')
