import mujoco, numpy as np, time
base=open('model_ref.xml').read()
ref=mujoco.MjModel.from_xml_path('model_ref.xml')
def sim(model, seed, ret=True):
    data=mujoco.MjData(model)
    nstep=int(2.0/model.opt.timestep)
    rng=np.random.default_rng(seed)
    data.qpos+=rng.normal(0,0.01,size=data.qpos.shape)
    mujoco.mj_forward(model,data)
    for _ in range(nstep):
        mujoco.mj_step(model,data)
    fp=mujoco.mjtState.mjSTATE_FULLPHYSICS
    s=np.zeros(mujoco.mj_stateSize(model,fp)); mujoco.mj_getState(model,data,s,fp); return s
def mk(opt):
    return mujoco.MjModel.from_xml_string(base.replace('<compiler autolimits="true"/>','<compiler autolimits="true"/>\n  %s'%opt))
def diff(m):
    return max(np.linalg.norm(sim(m,s)-sim(ref,s)) for s in [42,7,999])
def timeit(m,n=20):
    return np.median([ (lambda t: time.perf_counter()-t)(time.perf_counter()) or 0 for _ in range(0)]) if False else np.median([_t(m) for _ in range(n)])
def _t(m):
    t=time.perf_counter(); sim(m,np.random.randint(0,9999)); return time.perf_counter()-t
reft=np.median([_t(ref) for _ in range(20)])
for solver in ['PGS','CG','Newton']:
  for it in [1,2,3,5,8,12]:
    opt=f'<option jacobian="dense" solver="{solver}" iterations="{it}" ls_iterations="{max(it,1)}"><flag contact="disable"/></option>'
    try:
        m=mk(opt); d=diff(m)
        if d<1e-4:
            t=np.median([_t(m) for _ in range(20)])
            print(f'{solver:7s} it{it:2d} diff {d:.1e} t {t:.4f} pctg {t/reft:.3f}')
        else:
            print(f'{solver:7s} it{it:2d} diff {d:.1e} (skip)')
    except Exception as e:
        print(solver,it,'ERR',str(e)[:40])
print('ref',reft)
